//
// Build a Sentence — the 2026 Writing section's largest task (10 of its 12 items).
//
// The task is NOT a bare word scramble. Every item opens with a context line that
// the assembled sentence has to answer, the word bank holds 5-7 tiles that may be
// MULTI-WORD CHUNKS ("showed us around", "would like"), some items ship more tiles
// than slots, and some slots arrive already locked. Scoring is all-or-nothing.
// See BUILD_A_SENTENCE in src/data/toefl-2026-blueprint.ts.

/** Grammar structure the item targets, used for weak-area reporting. */
export type GrammarFocus = string;

export type BasCefr = "A1" | "A2" | "B1" | "B2" | "C1" | "C2";

export interface BuildASentenceItem {
  id: string;
  /** The line the assembled sentence must respond to. Always shown above the bank. */
  context: string;
  /**
   * The correct ordering of every chunk in the finished sentence, including the
   * chunks that arrive locked. Slot count === parts.length.
   */
  parts: string[];
  /** Indices into `parts` that are pre-placed and cannot be moved. */
  lockedIndices: number[];
  /** Extra tiles that belong in the bank but in no slot. */
  distractors: string[];
  /** The finished sentence, for review and for the AI evaluator. */
  sentence: string;
  grammarFocus: GrammarFocus;
  cefr: BasCefr;
}

/** Tiles offered in the word bank: the movable parts plus the distractors. */
export function bankTiles(item: BuildASentenceItem): string[] {
  return [
    ...item.parts.filter((_, i) => !item.lockedIndices.includes(i)),
    ...item.distractors,
  ];
}

/** Slot indices the test taker has to fill. */
export function openSlots(item: BuildASentenceItem): number[] {
  return item.parts.map((_, i) => i).filter((i) => !item.lockedIndices.includes(i));
}

/**
 * All-or-nothing, exactly as the exam scores it: every slot right, or zero.
 * `placed` maps slot index -> tile text.
 */
export function scoreBuildASentence(
  item: BuildASentenceItem,
  placed: Record<number, string | null>
): boolean {
  return openSlots(item).every((slot) => placed[slot] === item.parts[slot]);
}

